eSpace => {
    var ent_Order = eSpace.Entities.OfType<OutSystems.Model.Data.IServerEntity>().Named("Order");
    var ent_OrderLine = eSpace.Entities.OfType<OutSystems.Model.Data.IServerEntity>().Named("OrderLine");
    var ent_Product = eSpace.Entities.OfType<OutSystems.Model.Data.IServerEntity>().Named("Product");
    eSpace.CreateResource(Convert.FromBase64String(""), "SampleOrders.xlsx");
    var st_Excel_Orders = eSpace.CreateStructure("Excel_Orders");
    var st_Excel_Orders_OrderNumber = st_Excel_Orders.CreateAttribute("OrderNumber"); st_Excel_Orders_OrderNumber.DataType = eSpace.TextType; st_Excel_Orders_OrderNumber.Length = 20;
    var st_Excel_Orders_CustomerName = st_Excel_Orders.CreateAttribute("CustomerName"); st_Excel_Orders_CustomerName.DataType = eSpace.TextType; st_Excel_Orders_CustomerName.Length = 100;
    var st_Excel_Orders_Status = st_Excel_Orders.CreateAttribute("Status"); st_Excel_Orders_Status.DataType = eSpace.TextType; st_Excel_Orders_Status.Length = 20;
    var st_Excel_Orders_TotalAmount = st_Excel_Orders.CreateAttribute("TotalAmount"); st_Excel_Orders_TotalAmount.DataType = eSpace.DecimalType;
    var st_Excel_OrderLines = eSpace.CreateStructure("Excel_OrderLines");
    var st_Excel_OrderLines_OrderNumber = st_Excel_OrderLines.CreateAttribute("OrderNumber"); st_Excel_OrderLines_OrderNumber.DataType = eSpace.TextType; st_Excel_OrderLines_OrderNumber.Length = 20;
    var st_Excel_OrderLines_ProductCode = st_Excel_OrderLines.CreateAttribute("ProductCode"); st_Excel_OrderLines_ProductCode.DataType = eSpace.TextType; st_Excel_OrderLines_ProductCode.Length = 50;
    var st_Excel_OrderLines_Quantity = st_Excel_OrderLines.CreateAttribute("Quantity"); st_Excel_OrderLines_Quantity.DataType = eSpace.IntegerType;
    var st_Excel_OrderLines_UnitPrice = st_Excel_OrderLines.CreateAttribute("UnitPrice"); st_Excel_OrderLines_UnitPrice.DataType = eSpace.DecimalType;
    var act = eSpace.CreateServerAction("BootstrapOrdersFromExcel");
    act.Description = "Seeds orders and lines from SampleOrders.xlsx on publish when no XL- orders exist";
    var rec_Order = act.CreateLocalVariable("OrderRecord"); rec_Order.DataType = ent_Order;
    var rec_OrderLine = act.CreateLocalVariable("OrderLineRecord"); rec_OrderLine.DataType = ent_OrderLine;
    var start = act.CreateNode<OutSystems.Model.Logic.Nodes.IStartNode>();
    var guardAgg = act.CreateNode<OutSystems.Model.Logic.Nodes.IAggregateNode>("ExistingOrder").ConnectedBelow(start);
    guardAgg.AsDatabaseAggregate.CreateSource(ent_Order);
    guardAgg.AsDatabaseAggregate.CreateFilter("Order.OrderNumber like \"XL-%\"");
    var guardIf = act.CreateNode<OutSystems.Model.Logic.Nodes.IIfNode>().ConnectedBelow(guardAgg);
    guardIf.SetCondition("ExistingOrder.List.Empty"); guardIf.Label = "Not seeded yet?";
    var guardEnd = act.CreateNode<OutSystems.Model.Logic.Nodes.IEndNode>().ToTheRightOf(guardIf);
    guardIf.FalseTarget = guardEnd;
    var conv1 = act.CreateNode<OutSystems.Model.Logic.Nodes.IExcelToRecordListNode>("ConvertOrder").Below(guardIf);
    guardIf.TrueTarget = conv1;
    conv1.DataType = eSpace.GetOrCreateListType(eSpace.GetOrCreateAnonymousStructure(Tuple.Create<string, OutSystems.Model.Types.ITypeSignature>("Excel_Orders", st_Excel_Orders)));
    conv1.SetFileContent("Resources.SampleOrders_xlsx.Content");
    conv1.SetSheetName("\"Order\"");
    var conv2 = act.CreateNode<OutSystems.Model.Logic.Nodes.IExcelToRecordListNode>("ConvertOrderLine").ConnectedBelow(conv1);
    conv2.DataType = eSpace.GetOrCreateListType(eSpace.GetOrCreateAnonymousStructure(Tuple.Create<string, OutSystems.Model.Types.ITypeSignature>("Excel_OrderLines", st_Excel_OrderLines)));
    conv2.SetFileContent("Resources.SampleOrders_xlsx.Content");
    conv2.SetSheetName("\"OrderLine\"");
    var fe1 = act.CreateNode<OutSystems.Model.Logic.Nodes.IForEachNode>().ConnectedBelow(conv2);
    fe1.SetRecordList("ConvertOrder");
    var asg1 = act.CreateNode<OutSystems.Model.Logic.Nodes.IAssignNode>("PrepareOrder").ToTheRightOf(fe1);
    asg1.CreateAssignment("OrderRecord.OrderNumber", "ConvertOrder.Current.Excel_Orders.OrderNumber");
    asg1.CreateAssignment("OrderRecord.CustomerName", "ConvertOrder.Current.Excel_Orders.CustomerName");
    asg1.CreateAssignment("OrderRecord.Status", "ConvertOrder.Current.Excel_Orders.Status");
    asg1.CreateAssignment("OrderRecord.TotalAmount", "ConvertOrder.Current.Excel_Orders.TotalAmount");
    asg1.CreateAssignment("OrderRecord.OrderDate", "CurrDateTime()");
    var ex1 = act.CreateNode<OutSystems.Model.Logic.Nodes.IExecuteServerActionNode>("CreateOrder").ConnectedBelow(asg1);
    ex1.Action = ent_Order.CreateAction;
    ex1.SetArgumentValue(ent_Order.CreateAction.InputParameters.Named("Source"), "OrderRecord");
    fe1.CycleTarget = asg1;
    ex1.Target = fe1;
    var fe2 = act.CreateNode<OutSystems.Model.Logic.Nodes.IForEachNode>().Below(fe1);
    fe1.Target = fe2;
    fe2.SetRecordList("ConvertOrderLine");
    var find2_OrderNumber = act.CreateNode<OutSystems.Model.Logic.Nodes.IAggregateNode>("FindOrderForOrderLineOrderNumber").ToTheRightOf(fe2);
    find2_OrderNumber.AsDatabaseAggregate.CreateSource(ent_Order);
    find2_OrderNumber.AsDatabaseAggregate.CreateFilter("Order.OrderNumber = ConvertOrderLine.Current.Excel_OrderLines.OrderNumber");
    var find2_ProductCode = act.CreateNode<OutSystems.Model.Logic.Nodes.IAggregateNode>("FindProductForOrderLineProductCode").ConnectedBelow(find2_OrderNumber);
    find2_ProductCode.AsDatabaseAggregate.CreateSource(ent_Product);
    find2_ProductCode.AsDatabaseAggregate.CreateFilter("Product.ProductCode = ConvertOrderLine.Current.Excel_OrderLines.ProductCode");
    var asg2 = act.CreateNode<OutSystems.Model.Logic.Nodes.IAssignNode>("PrepareOrderLine").ConnectedBelow(find2_ProductCode);
    asg2.CreateAssignment("OrderLineRecord.OrderId", "FindOrderForOrderLineOrderNumber.List.Current.Order.Id");
    asg2.CreateAssignment("OrderLineRecord.ProductId", "FindProductForOrderLineProductCode.List.Current.Product.Id");
    asg2.CreateAssignment("OrderLineRecord.Quantity", "ConvertOrderLine.Current.Excel_OrderLines.Quantity");
    asg2.CreateAssignment("OrderLineRecord.UnitPrice", "ConvertOrderLine.Current.Excel_OrderLines.UnitPrice");
    asg2.CreateAssignment("OrderLineRecord.LineTotal", "ConvertOrderLine.Current.Excel_OrderLines.Quantity * ConvertOrderLine.Current.Excel_OrderLines.UnitPrice");
    var ex2 = act.CreateNode<OutSystems.Model.Logic.Nodes.IExecuteServerActionNode>("CreateOrderLine").ConnectedBelow(asg2);
    ex2.Action = ent_OrderLine.CreateAction;
    ex2.SetArgumentValue(ent_OrderLine.CreateAction.InputParameters.Named("Source"), "OrderLineRecord");
    fe2.CycleTarget = find2_OrderNumber;
    ex2.Target = fe2;
    var okEnd = act.CreateNode<OutSystems.Model.Logic.Nodes.IEndNode>().Below(fe2);
    fe2.Target = okEnd;

    var timer = eSpace.CreateTimer("BootstrapOrdersFromExcel");
    timer.Action = act;
    timer.Schedule = "WhenPublished";
    timer.TimeoutInMinutes = 20;
    timer.Description = "Seeds orders and lines from SampleOrders.xlsx on publish when no XL- orders exist";
}
